    truth = []
    for cl in clauses:
        mask = 0
        for idx in range(N):
            a = [(idx>>i)&1 for i in range(n)]
            val = 1
            for (v,s) in cl:
                lit = a[v] if s==1 else 1-a[v]
                val &= lit
            if val:
                mask |= (1<<idx)
        truth.append(mask)

    def check(subset):
        inter = (1<<N)-1
        for i in subset:
            inter &= truth[i]
        # input all-false: idx with low nvars bits 0
        for aux in range(1<<naux):
            idx = aux << nvars
            if inter>>idx & 1:
                return False
        # other inputs: at least one aux works
        for inp in range(1<<nvars):
            if inp == 0: continue
            ok=False
            for aux in range(1<<naux):
                idx = inp | (aux<<nvars)
                if inter>>idx & 1:
                    ok=True; break
            if not ok:
                return False
        return True

