        for subset in itertools.combinations(range(len(clauses)), k):
            if check(subset):
                print(f"FOUND nvars={nvars} naux={naux} k={k}")
                for i in subset:
                    print("   ", clauses[i])
                return True
    print(f"none nvars={nvars} naux={naux} up to k={maxk}")
    return False

