import itertools

def onein3_sat(nvars, clauses, assign):
    for (a,b,c) in clauses:
        cnt = assign[a-1] + assign[b-1] + assign[c-1]
        if cnt != 1:
            return False
    return True

def exists(nvars, clauses):
    for bits in itertools.product([0,1], repeat=nvars):
        if onein3_sat(nvars, clauses, list(bits)):
            return True
    return False

# Inequality gadget: vars 1=xT,2=xF,3=a,4=b,5=c
ineq = [(1,2,3),(1,2,4),(3,4,5)]
