for xT,xF in [(0,0),(0,1),(1,0),(1,1)]:
    # fix inputs by adding unit-like? we check existence with inputs fixed:
    # brute force over aux only
    ok=False
    for a,b,c in itertools.product([0,1],repeat=3):
        asg=[xT,xF,a,b,c]
        if onein3_sat(5, ineq, asg): ok=True
    print(f"  xT={xT} xF={xF}: sat={ok}")

