import itertools
import random

from problems import SOURCE, TARGET
from reduce import reduce


# ----------------------------------------------------------------------
# A small exact DPLL CNF solver (no external libraries).

def _simplify(clauses, lit):
    """Return clauses after assigning `lit` true, or None on conflict."""
    out = []
    for c in clauses:
        if lit in c:
            continue
        if -lit in c:
            nc = [x for x in c if x != -lit]
            if not nc:
                return None
            out.append(nc)
        else:
            out.append(c)
    return out


def solve_cnf(clauses) -> bool:
    """Exact satisfiability of a CNF given as a list of literal lists."""
    clauses = [list(c) for c in clauses]

    def rec(clauses) -> bool:
        while True:
            unit = None
            for c in clauses:
                if len(c) == 0:
                    return False
                if len(c) == 1:
                    unit = c[0]
                    break
            if unit is None:
                break
            clauses = _simplify(clauses, unit)
            if clauses is None:
                return False
        if not clauses:
            return True
        lit = clauses[0][0]
        for val in (lit, -lit):
            nxt = _simplify(clauses, val)
            if nxt is not None and rec(nxt):
                return True
        return False

    return rec(clauses)


